INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000cf47', 1, 'Crush the meat so that it is finite and we put it on a griddle to brown. Put the eggs, bacon and ham to fry.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000cf47', 2, 'Cut the bread in half, put the beef brisket, the fried eggs, the bacon, the ham, the mozzarella, the tomato and the lettuce. Cover with the other half of the bread and serve.');
INSERT INTO recipes (id, name, description, meal_type, servings) VALUES ('00000000-0000-4000-8000-00000000d05f', 'Classic Tourtière', 'Danie: Canadian. Źródło: TheMealDB', 'lunch', 4) ON CONFLICT (id) DO NOTHING;
